"""Deterministic stand-in used in M0, local dev and tests. Costs nothing."""

from __future__ import annotations

from pathlib import Path

from prism.models import Segment
from prism.providers.transcription.base import (
    Transcriber,
    TranscriptionOptions,
    TranscriptionResult,
)

_LINES = [
    "Welcome to this sample transcript generated by the fake provider.",
    "Real transcription arrives in milestone one with Azure Speech.",
    "Each segment has a start and end time in seconds.",
]


class FakeTranscriber(Transcriber):
    name = "fake"

    def transcribe(self, audio_path: Path, options: TranscriptionOptions) -> TranscriptionResult:
        segments = []
        t = 0.0
        for i, text in enumerate(_LINES):
            segments.append(
                Segment(
                    start=t,
                    end=t + 5.0,
                    text=text,
                    speaker=f"Speaker {i % 2 + 1}" if options.speaker_labels else None,
                )
            )
            t += 5.0
        return TranscriptionResult(
            segments=segments,
            language=options.language or "en",
            audio_seconds=t,
            method=self.name,
            model="fake",
        )
